    "John": {"age": 20, "grades": [90, 85, 95]},
    "Alice": {"age": 21, "grades": []},
    "Bob": {"age": 19, "grades": [80, 75, 85]}
}

print(calculate_average_grade(students))  # Output: {'John': 90.0, 'Alice': 0, 'Bob': 80.0}
```
